import ast, importlib.util, json, signal; from pathlib import Path; signal.alarm(45); import native_serve_profile as p; root=Path(importlib.util.find_spec('vllm').origin).parent; results=[]
for path,cls,name,category,scope in p.METHODS:
 file=root.parent/Path(path.replace('.','/')+'.py'); tree=ast.parse(file.read_text()); owner=next((n for n in tree.body if isinstance(n,ast.ClassDef) and n.name==cls),None); found=owner is not None and any(isinstance(n,ast.FunctionDef) and n.name==name for n in owner.body); results.append(dict(target=path+'.'+cls+'.'+name,resolved_source=found))
for path,name in p.FUNCTIONS:
 file=root.parent/Path(path.replace('.','/')+'.py'); tree=ast.parse(file.read_text()); found=any((isinstance(n,ast.FunctionDef) and n.name==name) or (isinstance(n,(ast.Import,ast.ImportFrom)) and any((a.asname or a.name)==name for a in n.names)) for n in tree.body); results.append(dict(target=path+'.'+name,resolved_source=found))
print(json.dumps(dict(vllm_root=str(root),source_symbols=results,all_resolved=all(r['resolved_source'] for r in results)),sort_keys=True))
